package it.paolofree.manutenzionemoto;
import android.content.Context;import android.graphics.*;import android.view.View;import android.animation.ValueAnimator;
public class NeonMotoView extends View{
 Paint p=new Paint(1);Path path=new Path();float progress;public NeonMotoView(Context c){super(c);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(5);p.setStrokeCap(Paint.Cap.ROUND);p.setColor(Color.rgb(64,235,255));p.setShadowLayer(16,0,0,p.getColor());setLayerType(LAYER_TYPE_SOFTWARE,p);ValueAnimator a=ValueAnimator.ofFloat(0,1);a.setDuration(1100);a.addUpdateListener(v->{progress=(float)v.getAnimatedValue();invalidate();});a.start();}
 protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),s=Math.min(w,h);path.reset();path.addCircle(w*.27f,h*.72f,s*.14f,Path.Direction.CW);path.addCircle(w*.74f,h*.72f,s*.14f,Path.Direction.CW);path.moveTo(w*.27f,h*.72f);path.lineTo(w*.43f,h*.46f);path.lineTo(w*.62f,h*.70f);path.lineTo(w*.27f,h*.72f);path.moveTo(w*.43f,h*.46f);path.lineTo(w*.69f,h*.43f);path.lineTo(w*.74f,h*.72f);path.moveTo(w*.42f,h*.45f);path.lineTo(w*.35f,h*.35f);path.lineTo(w*.50f,h*.35f);path.moveTo(w*.68f,h*.43f);path.lineTo(w*.76f,h*.30f);PathMeasure m=new PathMeasure(path,false);float total=0;do{total+=m.getLength();}while(m.nextContour());m.setPath(path,false);float remain=total*progress;Path out=new Path();do{float take=Math.min(remain,m.getLength());m.getSegment(0,take,out,true);remain-=take;}while(remain>0&&m.nextContour());c.drawPath(out,p);}
}
